function PortalMark({ portal, className }: { portal: Portal; className: string }) {
  if (portal.brand === 'aadhaar') {
    return <span className={`${className} portal-mark aadhaar-mark`} aria-hidden="true"><svg viewBox="0 0 40 40" fill="none"><path d="M20 3v6M20 31v6M3 20h6M31 20h6M8 8l4.3 4.3m15.4 15.4L32 32M32 8l-4.3 4.3M12.3 27.7 8 32" stroke="#ef6a37" strokeWidth="2.5" strokeLinecap="round"/><path d="M15 25c1.7-3 8.3-3 10 0M14.5 21.5c2.5-4 8.5-4 11 0M16 18.5c1.5-2.2 6.5-2.2 8 0M17.5 16.5c1.2-1.5 3.8-1.5 5 0" stroke="#7e2431" strokeWidth="1.8" strokeLinecap="round"/><circle cx="20" cy="20" r="15.2" stroke="#eaaa4b" strokeWidth="1.2"/></svg></span>
  }
  if (portal.brand === 'pan') {
    return <span className={`${className} portal-mark pan-mark`} aria-hidden="true"><span className="pan-lettering">PAN</span><span className="pan-rule"/><span className="pan-caption">INCOME TAX</span></span>
  }
  return <span className={className} aria-hidden="true">{portal.icon}</span>
}

